import{_ as t,o as r,c as a,a5 as n}from"./chunks/framework.BBrGrNbV.js";const u=JSON.parse('{"title":"Turing backend","description":"","frontmatter":{},"headers":[],"relativePath":"turing-backend.md","filePath":"turing-backend.md","lastUpdated":null}'),i={name:"turing-backend.md"};function s(o,e,d,l,c,g){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="Turing-backend" tabindex="-1">Turing backend <a class="header-anchor" href="#Turing-backend" aria-label="Permalink to &quot;Turing backend {#Turing-backend}&quot;">​</a></h1><p><code>TuringBRMI</code> is the direct-BRMI Turing backend. Loading Turing activates the package extension and turns the backend-neutral plan owned by BRM into a <code>DynamicPPL.Model</code>. Standard Turing inference APIs operate on its <code>model</code> field.</p><p>Executable models do not live on this backend-specific page. They are presented in the backend-neutral <a href="./feature-atlas">BRM feature atlas</a>, where every example shows BRM authoring, the emitted StanBlocks model, generated Stan, and the selected Turing model through the same four-pane comparison.</p><h2 id="Architecture" tabindex="-1">Architecture <a class="header-anchor" href="#Architecture" aria-label="Permalink to &quot;Architecture {#Architecture}&quot;">​</a></h2><p>The extension consumes <code>BRMI</code> analysis, materialized data, population designs, priors, observation semantics, and group-effect plans directly. It does not construct or inspect <code>SBBRMI</code>, <code>GenerativePlan</code>, a StanBlocks <code>SlicModel</code>, SLIC IR, or generated Stan. This boundary lets either backend become a weak dependency without changing BRM semantics.</p><p><code>TuringBRMI.plan</code> is the strict, backend-neutral semantic receipt; <code>TuringBRMI.model</code> is the executable Turing model. Unsupported surfaces fail during construction rather than being approximated silently. The feature atlas keeps that real construction error visible in the Turing pane.</p><h2 id="Parameterization" tabindex="-1">Parameterization <a class="header-anchor" href="#Parameterization" aria-label="Permalink to &quot;Parameterization {#Parameterization}&quot;">​</a></h2><p>Population coefficients use the shared design matrix, labels, and independent Normal priors. Gaussian scales use an explicit Exponential prior. Group effects default to a noncentered parameterization: plain random intercepts use a log scale and standard-normal latent values, correlated slopes use marginal scales plus an LKJ Cholesky factor, and <code>||</code> uses independent scales with no correlation variable. <code>centered_groups</code> selects the corresponding centered coefficient geometry for supported blocks; Stan-only adaptive/CV sizing controls remain loud construction errors.</p><p>Multiple and crossed grouping factors remain separate blocks. <code>gr(..., by=)</code> uses a separate scale/correlation frame per stratum. Matching <code>|ID|</code> terms in a distributional mean and precision predictor instead share one joint scale vector, LKJ factor, and group draw; each predictor consumes its own coefficient slice from that covariance block. Addressed <code>sd(...)</code> and <code>cor(...)</code> declarations reuse the same backend-neutral prior resolver as StanBlocks. Multi-membership remains fail-closed in Turing; the feature atlas keeps its real construction error beside the successful StanBlocks/Stan emission.</p><p>Canonical link declarations are lowered once in BRM and reused by the Turing executor. Response modifiers likewise carry materialized bounds, interval endpoints, and validation into the extension instead of being rediscovered from backend code.</p><h2 id="Outputs-and-replay" tabindex="-1">Outputs and replay <a class="header-anchor" href="#Outputs-and-replay" aria-label="Permalink to &quot;Outputs and replay {#Outputs-and-replay}&quot;">​</a></h2><p><code>turing_pointwise_loglikelihoods</code> returns response-named, row-aligned log-likelihood vectors; latent rows of a partly missing response remain <code>missing</code>. <code>turing_generated_quantities</code> evaluates the model&#39;s deterministic return value at one constrained draw. <code>turing_posterior_predictive</code> regenerates every response row at one constrained draw, including rows that were latent in the fitted model. For a fitted chain, <code>Turing.predict(backend, chain)</code> performs the same response-latent exclusion before running DynamicPPL&#39;s chain-level prediction.</p><p><code>reprocess(backend, new_data)</code> rebuilds the direct BRMI plan on new rows while reusing fitted centers, scales, categorical coordinates, interactions, offsets, and existing group coordinates. <code>freeze_constants=false</code> explicitly refits those preprocessing constants. Reusing existing groups is the fail-closed default. <code>resample_groups=:group</code> explicitly derives that grouping coordinate from <code>new_data</code>, keeps fitted population, scale, and correlation parameters, and regenerates only the named groups&#39; standardized effects. For a shared <code>|ID|</code> block this redraw remains joint across its predictors. Unseen categorical levels still fail closed.</p><h2 id="Parity-contract" tabindex="-1">Parity contract <a class="header-anchor" href="#Parity-contract" aria-label="Permalink to &quot;Parity contract {#Parity-contract}&quot;">​</a></h2><p>“Parity” means the same admitted BRMI has the same constrained prior and likelihood semantics, coefficient addressing, preprocessing behavior, and observable outputs in both backends. Producing a model that merely samples is not sufficient.</p><table tabindex="0"><thead><tr><th style="text-align:right;">BRMI surface</th><th style="text-align:right;">Turing status</th><th style="text-align:right;">Current contract</th></tr></thead><tbody><tr><td style="text-align:right;">Backend boundary</td><td style="text-align:right;"><strong>Supported</strong></td><td style="text-align:right;">Direct <code>BRMI</code> → backend-neutral plan → Turing extension; core loads without Turing</td></tr><tr><td style="text-align:right;">Population design</td><td style="text-align:right;"><strong>Partial</strong></td><td style="text-align:right;">Intercepts, raw and fitted numeric transforms, pure data expressions, offsets, treatment contrasts, and continuous/categorical interactions</td></tr><tr><td style="text-align:right;">Population priors</td><td style="text-align:right;"><strong>Partial</strong></td><td style="text-align:right;">Independent Normal defaults plus shared <code>effect(...)</code> specificity and addressing semantics</td></tr><tr><td style="text-align:right;">Gaussian identity</td><td style="text-align:right;"><strong>Supported</strong></td><td style="text-align:right;">Population and admitted grouped predictors with explicit Exponential scale prior</td></tr><tr><td style="text-align:right;">Bernoulli/Binomial logit</td><td style="text-align:right;"><strong>Supported</strong></td><td style="text-align:right;">Canonical linked declarations and explicit stable-logit families</td></tr><tr><td style="text-align:right;">Poisson log</td><td style="text-align:right;"><strong>Supported</strong></td><td style="text-align:right;">Canonical linked declarations, data offsets, and admitted grouped predictors</td></tr><tr><td style="text-align:right;">NegativeBinomial2</td><td style="text-align:right;"><strong>Supported subset</strong></td><td style="text-align:right;">Shared mean/precision population plans, independent multiple grouping blocks, and a joint cross-predictor `</td></tr><tr><td style="text-align:right;">BetaBinomial2</td><td style="text-align:right;"><strong>Supported subset</strong></td><td style="text-align:right;">Shared mean/precision population plans, independent multiple grouping blocks, and a joint cross-predictor `</td></tr><tr><td style="text-align:right;">Group effects</td><td style="text-align:right;"><strong>Partial</strong></td><td style="text-align:right;">Plain intercepts, correlated and exact-zero-correlation slopes, multiple/crossed factors, distributional cross-predictor `</td></tr><tr><td style="text-align:right;">Response evidence</td><td style="text-align:right;"><strong>Partial</strong></td><td style="text-align:right;">Truncated, censored, and interval-censored Normal/Poisson observations; wider modifiers remain pending</td></tr><tr><td style="text-align:right;">Missing responses</td><td style="text-align:right;"><strong>Supported subset</strong></td><td style="text-align:right;"><code>mi(y) ~ Normal(mu, sigma)</code> imputes missing rows from the same conditional family and keeps observed rows in the likelihood</td></tr><tr><td style="text-align:right;">Multiple responses</td><td style="text-align:right;"><strong>Supported subset</strong></td><td style="text-align:right;">Independent blocks are namespaced; exactly compatible shared predictors/group blocks are sampled once and reused, while partial or incompatible overlaps fail closed</td></tr><tr><td style="text-align:right;">Observation weights</td><td style="text-align:right;"><strong>Supported subset</strong></td><td style="text-align:right;">Analytic Normal weights rescale sigma; frequency and power weights scale density while predictive draws retain the base distribution</td></tr><tr><td style="text-align:right;">Advanced terms</td><td style="text-align:right;"><strong>Pending</strong></td><td style="text-align:right;">Splines, <code>t2</code>, <code>mo</code>, <code>me</code>, GP/HSGP, and kernel/ragged models fail loudly</td></tr><tr><td style="text-align:right;">Outputs</td><td style="text-align:right;"><strong>Supported subset</strong></td><td style="text-align:right;">Row-aligned pointwise likelihoods, deterministic returned quantities, one-draw posterior prediction, and chain-level Turing prediction; fitted response latents are excluded before regeneration</td></tr><tr><td style="text-align:right;">Replay</td><td style="text-align:right;"><strong>Supported subset</strong></td><td style="text-align:right;">Frozen preprocessing and existing-group coordinates replay on new rows; refitting constants and selective new-group resampling—including joint `</td></tr></tbody></table><p>The matrix is intentionally an overview. The build-generated examples and their current unsupported reasons are the executable source of truth.</p>',17)])])}const h=t(i,[["render",s]]);export{u as __pageData,h as default};
